def gen(rng):
    def fmt(cs):
        return str(len(cs)) + '\n' + '\n'.join(' '.join(map(str, c)) for c in cs)
    def rand_case(R, C):
        return (rng.randint(-C, C), rng.randint(-C, C), rng.randint(1, R), rng.randint(-C, C), rng.randint(-C, C), rng.randint(1, R))
    def constructed(R, C):
        kind = rng.randint(0, 6)
        r1 = rng.randint(1, R); r2 = rng.randint(1, R)
        x1 = rng.randint(-C, C); y1 = rng.randint(-C, C)
        if kind == 0:
            return (x1, y1, r1, x1, y1, r2)
        if kind in (1, 2):
            dist = r1 + r2 if kind == 1 else abs(r1 - r2)
            if dist == 0:
                dist = 1; r2 = r1 + 1 if kind == 2 else r2
            dx, dy = rng.choice([(dist, 0), (-dist, 0), (0, dist), (0, -dist)])
            return (x1, y1, r1, x1 + dx, y1 + dy, r2)
        if kind == 3:
            k = rng.randint(1, max(1, R // 5))
            a, b = rng.choice([(3, 4), (4, 3), (-3, 4), (3, -4)])
            return (x1, y1, 5 * k - 2 * k, x1 + a * k, y1 + b * k, 2 * k) if kind == 3 else None
        if kind == 4:
            return (x1, y1, r1, x1 + rng.randint(-C, C), y1 + rng.randint(-C, C), r2)
        if kind == 5:
            dist = r1 + r2 + rng.randint(1, 3)
            return (x1, y1, r1, x1 + dist, y1, r2)
        dist = abs(r1 - r2) + rng.randint(-1, 1)
        dist = max(1, dist)
        return (x1, y1, r1, x1, y1 + dist, r2)
    tests = [fmt([(0, 0, 5, 0, 0, 3), (0, 0, 2, 5, 0, 3), (0, 0, 2, 10, 0, 3)]),
             fmt([(0, 0, 5, 4, 0, 3), (0, 0, 10, 1, 0, 2), (0, 0, 5, 2, 0, 3)]),
             fmt([(0, 0, 1, 0, 0, 1)]), fmt([(0, 0, 1, 2, 0, 1)]), fmt([(0, 0, 5, 3, 4, 5)]), fmt([(0, 0, 5, 3, 4, 2)]),
             fmt([(-3, -4, 5, 0, 0, 10)]), fmt([(0, 0, 3, 0, 4, 1)])]
    for _ in range(40):
        n = rng.randint(1, 8)
        cs = []
        for _ in range(n):
            if rng.random() < 0.5:
                cs.append(rand_case(6, 6))
            else:
                cs.append(constructed(6, 6))
        tests.append(fmt(cs))
    N = 50000
    C = 10**6
    for mode in range(3):
        cs = []
        for _ in range(N):
            if mode == 0:
                cs.append(rand_case(C, C))
            else:
                cs.append(constructed(C, C // 3 if mode == 2 else C // 2))
        tests.append(fmt(cs))
    cs = [(-C, -C, C, C, C, C), (-C, -C, 1, C, C, C), (C, C, C, -C, -C, C)] * (N // 3)
    tests.append(fmt(cs))
    return tests
